import React from "react";

const About = () => {
    return (
        <div style={{ padding: "40px" }}>
            <h1>About ForgetAI</h1>
            <p>
                This project explores whether AI should forget like humans
                to improve intelligence, privacy, and adaptability.
            </p>
        </div>
    );
};

export default About;
